import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"Privacy","description":"","frontmatter":{"glossary":false},"headers":[],"relativePath":"PRIVACY.md","filePath":"PRIVACY.md","lastUpdated":1789092097000}`),a={name:`PRIVACY.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to “Privacy”">​</a></h1><p>GOAT is a local-first AI workspace. It stores chats and settings on your Mac and has no app analytics, automatic crash uploads or background update checks. Your choices about engines, tools, memory and previews determine which other services can receive data.</p><p>This page describes the current application and the static websites at goatapp.dev and goatherd.dev.</p><h2 id="the-application" tabindex="-1">The application <a class="header-anchor" href="#the-application" aria-label="Permalink to “The application”">​</a></h2><h3 id="local-storage" tabindex="-1">Local storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to “Local storage”">​</a></h3><p>Chats, attachments, settings, local memory and permission grants are stored on your Mac. Engine credentials currently use a file with owner-only permissions, rather than the macOS Keychain. GOAT does not provide its own encryption at rest. Account security, FileVault and backup protection are separate controls.</p><p>See <a href="/reference/STORAGE">Storage, backups and deletion</a> for locations and practical instructions. Removing the application does not remove its data or your workspace files.</p><h3 id="engines-and-tools" tabindex="-1">Engines and tools <a class="header-anchor" href="#engines-and-tools" aria-label="Permalink to “Engines and tools”">​</a></h3><p>The selected engine receives the context needed for a request. This can include messages, instructions, memory, selected attachments, tool definitions and tool results. Engines run separately from GOAT and can be configured on this Mac, a local network or a remote endpoint. A local address does not establish what that server does with received data.</p><p>MCP servers receive the tool arguments sent to them and run under their own process or service permissions. File tools can return approved workspace content to the conversation. Confined commands can access their authorised resources and may use the network only when explicitly enabled and permitted by policy. Review approvals before exposing confidential material.</p><h3 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h3><p>Local Markdown and LLM Wiki memory are stored in GOAT’s home directory. If you configure Hindsight, GOAT sends recall requests and retained context to the selected server and bank. Its operator controls retention, deletion, backups and any model services it uses. Changing providers does not delete records already retained by a previous provider.</p><h3 id="previews-and-other-applications" tabindex="-1">Previews and other applications <a class="header-anchor" href="#previews-and-other-applications" aria-label="Permalink to “Previews and other applications”">​</a></h3><p>Paddock can display generated HTML and diagrams. Preview resource requests follow the preview settings and JUDAS connection policy. Opening a link, document or service in another application transfers control to that application and its policies.</p><h3 id="connection-controls-and-diagnostics" tabindex="-1">Connection controls and diagnostics <a class="header-anchor" href="#connection-controls-and-diagnostics" aria-label="Permalink to “Connection controls and diagnostics”">​</a></h3><p>JUDAS governs GOAT’s managed connections. It is not a system-wide firewall and does not control every action taken independently by an engine, external MCP process or another application. The Activity Log records selected application events, not a complete network capture.</p><p>The Activity Log and performance signposts remain local unless you choose to share them. Diagnostic exports, screenshots and operating-system reports can contain project or device information. Review them before attaching them to an issue.</p><p>Read <a href="/JUDAS">Connection controls</a> and <a href="/overview/TOOLS">Tools and permissions</a> for the available choices.</p><h2 id="the-websites" tabindex="-1">The websites <a class="header-anchor" href="#the-websites" aria-label="Permalink to “The websites”">​</a></h2><p>The sites do not add analytics, advertising, tracking pixels, remote fonts or third-party embeds. Site assets and the documentation search index are served with the sites. There are no GOAT accounts or submission forms, and the site code does not set cookies.</p><p>The documentation site uses browser storage:</p><table tabindex="0"><thead><tr><th>Key</th><th>Storage</th><th>Purpose</th></tr></thead><tbody><tr><td><code>vitepress-theme-appearance</code></td><td>Local storage</td><td>Remember the selected appearance.</td></tr><tr><td><code>vitepress:local-search-detailed-list</code></td><td>Local storage</td><td>Remember the search result display preference.</td></tr><tr><td><code>vitepress:local-search-filter</code></td><td>Session storage</td><td>Retain the local search query during the browser session.</td></tr></tbody></table><p>Search runs in your browser. These values are not sent to a GOAT analytics service; clearing the site’s browser data removes them.</p><p>The production sites are intended for GitHub Pages hosting. GitHub processes hosting requests and logs visitors’ IP addresses for security purposes, including visitors who are not signed in. See <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages" target="_blank" rel="noreferrer">About GitHub Pages</a> and <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub’s privacy statement</a> for its practices.</p><p>Links to GitHub, engine projects and the sponsorship provider take you to independently operated services. Their privacy policies apply when you visit them. Sponsorship payments are handled by the linked provider, not these static sites.</p><h2 id="community-contributions-and-questions" tabindex="-1">Community contributions and questions <a class="header-anchor" href="#community-contributions-and-questions" aria-label="Permalink to “Community contributions and questions”">​</a></h2><p>GitHub issues, pull requests and discussions can be public. Do not include credentials, private conversations or confidential project files. Information you voluntarily submit is handled by the relevant platform and the maintainers who receive it.</p><p>For privacy questions or requests, email <a href="mailto:privacy@goatapp.dev" target="_blank" rel="noreferrer">privacy@goatapp.dev</a>. For general enquiries, email <a href="mailto:baa@goatapp.dev" target="_blank" rel="noreferrer">baa@goatapp.dev</a>. Send vulnerability reports through the <a href="https://github.com/goatsoft/GOAT/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security reporting channels</a>; do not include private information in a public issue.</p>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};